const Z_PRESETS = {
  bapps:2, bapps2:2, w23:2, w22:2, w24:2, w25:2, w26:2, w28:2, w29:2, w27:2, w31:2, w32:2, w61:2,
  w30:1, w33:1, w34:1,
  ramp:0, tramp:0, w40:0, w41:0, w42:0, w44:0, w45:0, w46:0,
  w9:0, w10:0, w11:0, w12:0, w14:0, w15:0, w16:0, w17:0, w18:0,
  w1:0, w2:0, w3:0, w4:0, w5:0, w6:0, w7:0, w13:0,
  tsp:0, tmid:0, mid:0, midc:0, w19:0, w20:0, w21:0, w58:0, w59:0, w60:0, win:0, w49:0, w50:0, w51:0,
  asite:0, bsite:0, bct:0, ctsp:0, aan:0,
  w35:0, w36:0, w37:0, w38:0, w39:0, w43:0, w47:0,
  w52:0, w53:0, w54:0, w55:0, w56:0, w57:0, w62:0,
};

let WALLS = [];
let NAV_BLOCKERS = [];
let GRENADES = [];
let ACTIVE_GRENADES = [];
let TRACERS = [];
let WP = {}, EDGES = [], ADJ = {};

function buildGraph(){
  WP = {};
  Object.entries(GRAPH_RAW.n).forEach(([k, v]) => {
    const nx = Number(v?.[0]) || 0, ny = Number(v?.[1]) || 0;
    const z = (Array.isArray(v) && v.length > 2) ? (Number(v[2]) || 0) : (Z_PRESETS[k] || 0);
    WP[k] = { x: nx * RADAR_SIZE, y: ny * RADAR_SIZE, z };
  });
  EDGES = GRAPH_RAW.e.map(e => [e.a, e.b]);
  buildAdjFromEdges();
}
function buildAdjFromEdges(){
  for (const k in ADJ) delete ADJ[k];
  EDGES.forEach(([a,b])=>{
    (ADJ[a] = ADJ[a] || []).push(b);
    (ADJ[b] = ADJ[b] || []).push(a);
  });
}
buildGraph();

function normalizeWalls(){
  if (!Array.isArray(WALLS)) WALLS = [];
  WALLS.forEach(w => {
    if (!w.shape) w.shape = 'rect';
    if (w.z === undefined) w.z = 0;
    if (w.hh === undefined) w.hh = 100;
    if (w.shape === 'rect'){ w.x = Number(w.x)||0; w.y = Number(w.y)||0; w.w = Number(w.w)||0; w.h = Number(w.h)||0; }
    if (w.shape === 'poly' && !Array.isArray(w.points)) w.points = [];
  });
}
function normalizeNavBlockers(){
  if (!Array.isArray(NAV_BLOCKERS)) NAV_BLOCKERS = [];
  NAV_BLOCKERS.forEach(b=>{
    if (!b.shape) b.shape='rect';
    if (!Array.isArray(b.layers) || !b.layers.length) b.layers=[-2,-1,0,1,2,3];
    b.layers=[...new Set(b.layers.map(Number).filter(Number.isFinite))].map(x=>Math.round(x));
    if (b.shape==='rect'){ b.x=Number(b.x)||0; b.y=Number(b.y)||0; b.w=Number(b.w)||0; b.h=Number(b.h)||0; }
    if (b.shape==='poly' && !Array.isArray(b.points)) b.points=[];
    b.vision = b.vision !== false;
  });
}
function normalizeGrenades(){
  if (!Array.isArray(GRENADES)) GRENADES=[];
  GRENADES.forEach((g,i)=>{
    g.id = g.id || ('g'+Date.now().toString(36)+'_'+i);
    g.type = ['smoke','flash','he','molotov'].includes(g.type) ? g.type : 'smoke';
    g.team = ['T','CT','both'].includes(g.team) ? g.team : 'T';
    g.from = g.from || {x:0,y:0,z:0}; g.to = g.to || {x:0,y:0,z:0};
    ['from','to'].forEach(k=>{ g[k].x=Number(g[k].x)||0; g[k].y=Number(g[k].y)||0; g[k].z=Number(g[k].z)||0; });
    g.enabled = g.enabled !== false;
  });
}
normalizeWalls();
WALLS = Array.isArray(WALLS) && WALLS.length ? WALLS : DEFAULT_WALLS.map(w=>JSON.parse(JSON.stringify(w)));
normalizeNavBlockers();
normalizeGrenades();

function loadSaved(){
  try {
    const saved = localStorage.getItem('cs2_radar_full_v6');
    if (!saved) return;
    const data = JSON.parse(saved);
    if (data.n && data.e){
      WP = {};
      Object.entries(data.n).forEach(([k, v])=>{
        const [x, y] = v;
        const isNorm = x <= 2 && y <= 2;
        const z = (Array.isArray(v) && v.length > 2) ? v[2] : (Z_PRESETS[k] || 0);
        WP[k] = isNorm ? { x: x*RADAR_SIZE, y: y*RADAR_SIZE, z } : { x, y, z };
      });
      EDGES = data.e.map(e => [e.a, e.b]);
      if (Array.isArray(data.walls)) WALLS = data.walls.map(w => ({...w}));
      if (Array.isArray(data.navBlockers)) NAV_BLOCKERS = data.navBlockers.map(w => ({...w, points:Array.isArray(w.points)?w.points.map(p=>({...p})):w.points}));
      if (Array.isArray(data.grenades)) GRENADES = data.grenades.map(g => JSON.parse(JSON.stringify(g)));
      normalizeWalls(); normalizeNavBlockers(); normalizeGrenades();
      buildAdjFromEdges();
      console.log('[Radar] Загружено из localStorage');
    }
  } catch(e){ console.warn('Ошибка загрузки', e); }
}
loadSaved();
normalizeWalls();

const SITES = { A:{x:0,y:0,r:55}, B:{x:0,y:0,r:55} };
function refreshSites(){
  if (WP.asite) SITES.A = { x: WP.asite.x, y: WP.asite.y, r: 55 };
  if (WP.bsite) SITES.B = { x: WP.bsite.x, y: WP.bsite.y, r: 55 };
}
refreshSites();

let saveTimer = null;
function autoSave(){
  clearTimeout(saveTimer);
  saveTimer = setTimeout(()=>{
    try {
      const cleanGrenades = GRENADES.map(g=>{const { _usedRound, ...clean } = g; return clean;});
      const out = { n: {}, e: EDGES.map(([a,b])=>({a,b})), walls: WALLS, navBlockers: NAV_BLOCKERS, grenades: cleanGrenades };
      Object.entries(WP).forEach(([k,p])=>{ out.n[k] = [ +(p.x/RADAR_SIZE).toFixed(6), +(p.y/RADAR_SIZE).toFixed(6), p.z||0 ]; });
      localStorage.setItem('cs2_radar_full_v6', JSON.stringify(out));
    } catch(e){ console.warn('AutoSave failed', e); }
  }, 500);
}

/* ============ ГЕОМЕТРИЯ ============ */
function pointInPolygon(x, y, pts){
  if (!pts || pts.length < 3) return false;
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++){
    const xi = pts[i].x, yi = pts[i].y;
    const xj = pts[j].x, yj = pts[j].y;
    const intersect = ((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}
function segSegT(x1,y1,x2,y2,x3,y3,x4,y4){
  const d = (x2-x1)*(y4-y3) - (y2-y1)*(x4-x3);
  if (Math.abs(d) < 1e-9) return null;
  const t = ((x3-x1)*(y4-y3) - (y3-y1)*(x4-x3)) / d;
  const u = ((x3-x1)*(y2-y1) - (y3-y1)*(x2-x1)) / d;
  if (t >= 0 && t <= 1 && u >= 0 && u <= 1) return t;
  return null;
}
function rayRectEntryT(x1, y1, x2, y2, r){
  const dx = x2 - x1, dy = y2 - y1;
  let tmin = 0, tmax = 1;
  if (Math.abs(dx) < 1e-9){
    if (x1 < r.x || x1 > r.x + r.w) return null;
  } else {
    const t1 = (r.x - x1) / dx, t2 = (r.x + r.w - x1) / dx;
    const lo = Math.min(t1, t2), hi = Math.max(t1, t2);
    tmin = Math.max(tmin, lo); tmax = Math.min(tmax, hi);
  }
  if (Math.abs(dy) < 1e-9){
    if (y1 < r.y || y1 > r.y + r.h) return null;
  } else {
    const t1 = (r.y - y1) / dy, t2 = (r.y + r.h - y1) / dy;
    const lo = Math.min(t1, t2), hi = Math.max(t1, t2);
    tmin = Math.max(tmin, lo); tmax = Math.min(tmax, hi);
  }
  if (tmin > tmax) return null;
  return tmin;
}
function rayPolyEntryT(x1, y1, x2, y2, pts){
  if (!pts || pts.length < 3) return null;
  let best = null;
  for (let i = 0; i < pts.length; i++){
    const a = pts[i], b = pts[(i + 1) % pts.length];
    const t = segSegT(x1, y1, x2, y2, a.x, a.y, b.x, b.y);
    if (t !== null && (best === null || t < best)) best = t;
  }
  return best;
}
function rayWallEntryT(x1, y1, x2, y2, w){
  const shape = w.shape || 'rect';
  if (shape === 'rect') return rayRectEntryT(x1, y1, x2, y2, w);
  return rayPolyEntryT(x1, y1, x2, y2, w.points);
}

function wallBlocksPlayer(w, playerZ){
  const pBase = (Number(playerZ) || 0) * FLOOR_UNIT;
  const pTop  = pBase + EYE_HEIGHT;
  const wBase = (Number(w.z) || 0) * FLOOR_UNIT;
  const wTop  = wBase + (Number(w.hh) || 100);
  if (wTop - wBase <= STEP_HEIGHT) return false;
  if (wTop <= pBase + STEP_HEIGHT) return false;
  if (wBase >= pTop) return false;
  return true;
}
function isInsideWall(x, y, atZ){
  const z = Number(atZ) || 0;
  for (const w of WALLS){
    if (!wallBlocksPlayer(w, z)) continue;
    const shape = w.shape || 'rect';
    if (shape === 'rect'){
      if (x >= w.x && x <= w.x + w.w && y >= w.y && y <= w.y + w.h) return true;
    } else if (shape === 'poly'){
      if (pointInPolygon(x, y, w.points)) return true;
    }
  }
  return false;
}
function tryMove(px, py, nx, ny, atZ){
  const z = Number(atZ) || 0;
  if (!pointBlockedForMovement(nx, ny, z)) return [nx, ny];
  if (!pointBlockedForMovement(px, ny, z)) return [px, ny];
  if (!pointBlockedForMovement(nx, py, z)) return [nx, py];
  const hx = px + (nx - px) * 0.5;
  const hy = py + (ny - py) * 0.5;
  if (!pointBlockedForMovement(hx, hy, z)) return [hx, hy];
  if (!pointBlockedForMovement(hx, py, z)) return [hx, py];
  if (!pointBlockedForMovement(px, hy, z)) return [px, hy];
  return [px, py];
}

function edgeBlockedByWall(ax, ay, bx, by, atZ){
  const z = Number(atZ) || 0;
  for (const w of WALLS){
    if (!wallBlocksPlayer(w, z)) continue;
    const t = rayWallEntryT(ax, ay, bx, by, w);
    if (t !== null) return true;
  }
  return false;
}
function navLayerForZ(z){ return Math.round(Number(z)||0); }
function shapeContains(x,y,b){
  const shape=b.shape||'rect';
  if(shape==='rect') return x>=b.x && x<=b.x+b.w && y>=b.y && y<=b.y+b.h;
  return pointInPolygon(x,y,b.points);
}
function navBlockerActive(b,z){ return Array.isArray(b.layers) && b.layers.includes(navLayerForZ(z)); }
function edgeBlockedByNavBlocker(ax,ay,bx,by,zA,zB){
  for(const b of NAV_BLOCKERS){
    if(!b || !b.layers?.length) continue;
    const t=rayWallEntryT(ax,ay,bx,by,b);
    if(t===null) continue;
    const z=(Number(zA)||0)+((Number(zB)||0)-(Number(zA)||0))*t;
    if(navBlockerActive(b,z)) return true;
  }
  return false;
}
function edgeBlockedByGeometry(ax,ay,bx,by,zA,zB){
  const za=Number(zA)||0, zb=Number(zB)||0;
  for(const w of WALLS){
    const t=rayWallEntryT(ax,ay,bx,by,w);
    if(t===null) continue;
    const z=za+(zb-za)*t;
    if(wallBlocksPlayer(w,z)) return true;
  }
  if(edgeBlockedByNavBlocker(ax,ay,bx,by,za,zb)) return true;
  return false;
}
function wpEdgeBlocked(aKey,bKey,atZ=null){
  const A=WP[aKey], B=WP[bKey];
  if(!A||!B) return true;
  const za=atZ===null?A.z:Number(atZ)||0;
  const zb=atZ===null?B.z:Number(atZ)||0;
  return edgeBlockedByGeometry(A.x,A.y,B.x,B.y,za,zb);
}
function pointBlockedForMovement(x,y,z){ return isInsideWall(x,y,z) || NAV_BLOCKERS.some(b=>navBlockerActive(b,z)&&shapeContains(x,y,b)); }
function lineBlockedByNavVision(ax,ay,bx,by,zA,zB){
  for(const b of NAV_BLOCKERS){
    if(!b.vision || !b.layers?.length) continue;
    const t=rayWallEntryT(ax,ay,bx,by,b);
    if(t===null) continue;
    const z=(Number(zA)||0)+((Number(zB)||0)-(Number(zA)||0))*t;
    if(navBlockerActive(b,z)) return true;
  }
  return false;
}

function hasLOS(a, b){
  const zA = Number(a.z) || 0;
  const zB = Number(b.z) || 0;
  if (Math.abs(zA - zB) > 1) return false;
  if (smokeBetween(a,b)) return false;
  const eyeA = zA * FLOOR_UNIT + EYE_HEIGHT;
  const eyeB = zB * FLOOR_UNIT + EYE_HEIGHT;
  for (const w of WALLS){
    const t = rayWallEntryT(a.x, a.y, b.x, b.y, w);
    if (t === null) continue;
    const rayZ = (Number(a.z)||0) + ((Number(b.z)||0)-(Number(a.z)||0))*t;
    const eyeRayZ = eyeA + (eyeB - eyeA) * t;
    const wallBase = (Number(w.z) || 0) * FLOOR_UNIT;
    const wallTop  = wallBase + (Number(w.hh) || 100);
    if (eyeRayZ >= wallBase && eyeRayZ <= wallTop) return false;
  }
  if(lineBlockedByNavVision(a.x,a.y,b.x,b.y,a.z,b.z)) return false;
  return true;
}

function findPath(from, to, atZ=null, avoidSmoke=false){
  if (!WP[from] || !WP[to]) return null;
  if (from === to) return [from];
  const q = [[from]], seen = new Set([from]);
  while (q.length){
    const p = q.shift(), last = p[p.length-1];
    for (const n of (ADJ[last] || [])){
      if (seen.has(n)) continue;
      const node=WP[n];
      if (!node) continue;
      const nodeZ=atZ===null?(Number(node.z)||0):(Number(atZ)||0);
      if (pointBlockedForMovement(node.x,node.y,nodeZ)) continue;
      if (wpEdgeBlocked(last,n,atZ)) continue;
      if (avoidSmoke && edgeCrossesActiveSmoke(WP[last],WP[n])) continue;
      const next = [...p,n];
      if (n === to) return next;
      seen.add(n); q.push(next);
    }
  }
  return null;
}
function findPathAny(from, to){
  if (from === to) return [from];
  return findPath(from,to,null);
}

function projectOnSegment(px, py, x1, y1, x2, y2){
  const dx = x2-x1, dy = y2-y1;
  const len2 = dx*dx + dy*dy;
  if (len2 === 0) return { x: x1, y: y1, t: 0 };
  let t = ((px-x1)*dx + (py-y1)*dy) / len2;
  t = Math.max(0, Math.min(1, t));
  return { x: x1 + t*dx, y: y1 + t*dy, t };
}
function pointToSegmentDistance(px, py, x1, y1, x2, y2){
  const dx = x2 - x1, dy = y2 - y1;
  const len2 = dx*dx + dy*dy;
  if (len2 === 0) return { dist: Math.hypot(px - x1, py - y1), t: 0, x: x1, y: y1 };
  let t = ((px - x1)*dx + (py - y1)*dy) / len2;
  t = Math.max(0, Math.min(1, t));
  const cx = x1 + t*dx, cy = y1 + t*dy;
  return { dist: Math.hypot(px - cx, py - cy), t, x: cx, y: cy };
}

/* === ВЫТАЛКИВАНИЕ ИЗ СТЕНЫ === */
function pushOutOfWall(p){
  if (!p || !p.alive) return false;
  const z = Number(p.z) || 0;
  if (!isInsideWall(p.x, p.y, z)) return false;
  for (let r = 4; r <= 120; r += 4){
    const samples = Math.max(8, Math.floor(r * 0.6));
    for (let a = 0; a < samples; a++){
      const ang = (a / samples) * Math.PI * 2;
      const nx = p.x + Math.cos(ang) * r;
      const ny = p.y + Math.sin(ang) * r;
      if (nx < 10 || nx > RADAR_SIZE - 10) continue;
      if (ny < 10 || ny > RADAR_SIZE - 10) continue;
      if (!pointBlockedForMovement(nx, ny, z)){
        p.x = nx; p.y = ny;
        p.lastX = nx; p.lastY = ny;
        p.stuckFrames = 0;
        return true;
      }
    }
  }
  return false;
}

