  if(e.button===2){e.preventDefault();if(R.selectedWP&&hitWP&&R.selectedWP!==hitWP){const exists=EDGES.some(([a,b])=>(a===R.selectedWP&&b===hitWP)||(a===hitWP&&b===R.selectedWP));if(!exists){EDGES.push([R.selectedWP,hitWP]);buildAdjFromEdges();autoSave();updateEditInfo();}}return;}
  if(hitWP){R.selectedWP=hitWP;R.draggingWP=hitWP;updateEditInfo();return;}
  if(hitEdge!==null){EDGES.splice(hitEdge,1);buildAdjFromEdges();autoSave();updateEditInfo();return;}
