function onCanvasMove(e){
  if(!cv)return;
  if(cam._panning){const cssPerCanvas=cam._cssPerCanvas||1;cam.panX=cam._startPanX+(e.clientX-cam._startX)/cssPerCanvas;cam.panY=cam._startPanY+(e.clientY-cam._startY)/cssPerCanvas;return;}
  const {x,y}=canvasCoords(e);R.mouseX=x;R.mouseY=y;if(!R.editMode)return;
  if(R.editSubmode==='walls'||R.editSubmode==='blockers'){
    const isBlocker=R.editSubmode==='blockers';
    if(isBlocker&&R.draggingBlockerVertex){const b=NAV_BLOCKERS[R.draggingBlockerVertex.blockerIdx];if(b?.points?.[R.draggingBlockerVertex.vertexIdx]){b.points[R.draggingBlockerVertex.vertexIdx].x=x;b.points[R.draggingBlockerVertex.vertexIdx].y=y;}return;}
    if(isBlocker&&R.draggingBlocker){const d=R.draggingBlocker,b=NAV_BLOCKERS[d.idx];if(b){if(b.shape==='poly'){const dx=x-d.offsetX,dy=y-d.offsetY;b.points=d.origPoints.map(p=>({x:p.x+dx,y:p.y+dy}));}else{b.x=x-d.offsetX;b.y=y-d.offsetY;}}return;}
    if(!isBlocker&&R.draggingVertex){const w=WALLS[R.draggingVertex.wallIdx];if(w?.points?.[R.draggingVertex.vertexIdx]){w.points[R.draggingVertex.vertexIdx].x=x;w.points[R.draggingVertex.vertexIdx].y=y;}return;}
    if(!isBlocker&&R.draggingPolygon){const d=R.draggingPolygon,w=WALLS[d.idx];if(w){const dx=x-d.offsetX,dy=y-d.offsetY;w.points=d.origPoints.map(p=>({x:p.x+dx,y:p.y+dy}));}return;}
    if(isBlocker&&R.drawingBlocker){R.drawingBlocker.x2=x;R.drawingBlocker.y2=y;return;}
    if(!isBlocker&&R.drawingWall){R.drawingWall.x2=x;R.drawingWall.y2=y;return;}
    if(!isBlocker&&R.draggingWall&&WALLS[R.draggingWall.idx]){WALLS[R.draggingWall.idx].x=x-R.draggingWall.offsetX;WALLS[R.draggingWall.idx].y=y-R.draggingWall.offsetY;return;}
    if(R.wallShape==='pen'){R.penHover={x,y};return;}return;
  }
  if(R.editSubmode==='grenades'){
    if(R.draggingGrenadePoint){const g=GRENADES[R.draggingGrenadePoint.index];if(g){g[R.draggingGrenadePoint.side].x=x;g[R.draggingGrenadePoint.side].y=y;}}return;
  }
  R.hoveredEdge=findEdgeUnder(x,y,12);if(R.draggingWP&&WP[R.draggingWP]){WP[R.draggingWP].x=x;WP[R.draggingWP].y=y;}
}
function onCanvasUp(){
  if(cam._panning){cam._panning=false;cv.style.cursor='crosshair';}
  if(R.drawingWall){const d=R.drawingWall,rx=Math.min(d.x1,d.x2),ry=Math.min(d.y1,d.y2),rw=Math.abs(d.x2-d.x1),rh=Math.abs(d.y2-d.y1);if(rw>8&&rh>8){WALLS.push({shape:'rect',x:rx,y:ry,w:rw,h:rh,z:0,hh:100});R.selectedWall=WALLS.length-1;autoSave();updateEditInfo();}R.drawingWall=null;}
  if(R.drawingBlocker){const d=R.drawingBlocker,rx=Math.min(d.x1,d.x2),ry=Math.min(d.y1,d.y2),rw=Math.abs(d.x2-d.x1),rh=Math.abs(d.y2-d.y1);if(rw>8&&rh>8){NAV_BLOCKERS.push({shape:'rect',x:rx,y:ry,w:rw,h:rh,layers:[...R.blockerLayers],vision:R.blockerVision});R.selectedBlocker=NAV_BLOCKERS.length-1;autoSave();updateEditInfo();}R.drawingBlocker=null;}
  if(R.draggingWall||R.draggingPolygon||R.draggingVertex||R.draggingWP||R.draggingBlocker||R.draggingBlockerVertex||R.draggingGrenadePoint)autoSave();
  R.draggingWall=null;R.draggingPolygon=null;R.draggingVertex=null;R.draggingWP=null;R.draggingBlocker=null;R.draggingBlockerVertex=null;R.draggingGrenadePoint=null;
}
function onCanvasDblClick(e){
  if(!R.editMode)return;
  if((R.editSubmode==='walls'||R.editSubmode==='blockers')&&R.wallShape==='pen'&&R.penPoints.length>=3){finishPen();return;}
  const {x,y}=canvasCoords(e);
  if(R.editSubmode==='walls'||R.editSubmode==='blockers'){
    const list=R.editSubmode==='blockers'?NAV_BLOCKERS:WALLS,edge=findShapeEdgeUnder(x,y,list);
    if(edge){const w=list[edge.shapeIdx],a=edge.edgeIdx,b=(a+1)%w.points.length,adaptive=VERTEX_HIT_RADIUS/Math.max(0.2,cam.zoom),da=Math.hypot(w.points[a].x-x,w.points[a].y-y),db=Math.hypot(w.points[b].x-x,w.points[b].y-y);if(da>adaptive&&db>adaptive){w.points.splice(a+1,0,{x:edge.px,y:edge.py});if(R.editSubmode==='blockers'){R.selectedBlocker=edge.shapeIdx;R.draggingBlockerVertex={blockerIdx:edge.shapeIdx,vertexIdx:a+1};}else{R.selectedWall=edge.shapeIdx;R.draggingVertex={wallIdx:edge.shapeIdx,vertexIdx:a+1};}autoSave();updateEditInfo();}}return;
  }
  if(R.editSubmode==='grenades'){
    const gl=findGrenadeLineUnder(x,y,12);if(gl){R.selectedGrenade=gl.index;const g=GRENADES[gl.index];const t=prompt('Тип: smoke / flash / he / molotov',g.type);if(['smoke','flash','he','molotov'].includes(t)){g.type=t;autoSave();updateEditInfo();}return;}return;
  }
  const hitWP=findWPUnder(x,y,25);if(!hitWP)return;const oldName=hitWP,newName=prompt('Новое имя точки:',oldName);if(!newName||newName===oldName)return;if(WP[newName]){if(!confirm(`Точка "${newName}" уже существует. Заменить?`))return;delete WP[newName];EDGES=EDGES.filter(([a,b])=>a!==newName&&b!==newName);}WP[newName]=WP[oldName];delete WP[oldName];EDGES=EDGES.map(([a,b])=>[a===oldName?newName:a,b===oldName?newName:b]);if(oldName==='asite'||newName==='asite'||oldName==='bsite'||newName==='bsite')refreshSites();R.selectedWP=newName;buildAdjFromEdges();autoSave();updateEditInfo();
}

window.addEventListener('keydown',e=>{
  if(!R.editMode)return;
  if((R.editSubmode==='walls'||R.editSubmode==='blockers')&&R.wallShape==='pen'){
    if(e.key==='Enter'){finishPen();e.preventDefault();return;}
    if(e.key==='Escape'){R.penPoints=[];R.penHover=null;updateEditInfo();e.preventDefault();return;}
  }
  if(e.key==='Delete'||e.key==='Backspace'){
    if(R.editSubmode==='walls'&&R.selectedWall!==null){WALLS.splice(R.selectedWall,1);R.selectedWall=null;autoSave();updateEditInfo();e.preventDefault();return;}
    if(R.editSubmode==='blockers'&&R.selectedBlocker!==null){NAV_BLOCKERS.splice(R.selectedBlocker,1);R.selectedBlocker=null;autoSave();updateEditInfo();e.preventDefault();return;}
    if(R.editSubmode==='grenades'&&R.selectedGrenade!==null){GRENADES.splice(R.selectedGrenade,1);R.selectedGrenade=null;autoSave();updateEditInfo();e.preventDefault();return;}
    if(R.selectedWP){delete WP[R.selectedWP];EDGES=EDGES.filter(([a,b])=>a!==R.selectedWP&&b!==R.selectedWP);buildAdjFromEdges();R.selectedWP=null;autoSave();updateEditInfo();e.preventDefault();}
  }
});
function setZ(value){
  if(R.editSubmode==='walls'&&R.selectedWall!==null){WALLS[R.selectedWall].z=value;autoSave();updateEditInfo();}
  else if(R.selectedWP&&WP[R.selectedWP]){WP[R.selectedWP].z=value;autoSave();updateEditInfo();}
}
function setHH(value){if(R.editSubmode==='walls'&&R.selectedWall!==null){WALLS[R.selectedWall].hh=value;autoSave();updateEditInfo();}}
function setBlockerLayer(layer,on){
  const n=Math.round(Number(layer));
  if(on&&!R.blockerLayers.includes(n))R.blockerLayers.push(n);
  if(!on)R.blockerLayers=R.blockerLayers.filter(x=>x!==n);
  if(!R.blockerLayers.length)R.blockerLayers=[0];
  if(R.editSubmode==='blockers'&&R.selectedBlocker!==null){NAV_BLOCKERS[R.selectedBlocker].layers=[...R.blockerLayers];autoSave();}
  updateEditInfo();
}
function setBlockerVision(v){R.blockerVision=!!v;if(R.selectedBlocker!==null&&NAV_BLOCKERS[R.selectedBlocker]){NAV_BLOCKERS[R.selectedBlocker].vision=!!v;autoSave();}updateEditInfo();}
function setGrenadeType(v){
  if(!['smoke','flash','he','molotov'].includes(v)) return;
  R.grenadeType=v;
  if(R.editSubmode==='grenades' && R.selectedGrenade!==null && GRENADES[R.selectedGrenade]){
    GRENADES[R.selectedGrenade].type=v; autoSave();
  }
  updateEditInfo();
}
function setGrenadeTeam(v){
  if(!['T','CT','both'].includes(v)) return;
  R.grenadeTeam=v;
  if(R.editSubmode==='grenades' && R.selectedGrenade!==null && GRENADES[R.selectedGrenade]){
    GRENADES[R.selectedGrenade].team=v; autoSave();
  }
  updateEditInfo();
}
function setWallShapeTool(shape){R.wallShape=shape;R.penPoints=[];R.penHover=null;document.querySelectorAll('.cs2-rf-shape').forEach(b=>{const active=b.dataset.shape===shape;b.style.background=active?'#9b59b6':'#1a2230';b.style.color=active?'#000':'#9b59b6';});renderTips();updateEditInfo();}

function scanBlockedEdges(){
  const bad = [];
  EDGES.forEach(([a,b], idx) => {
    const A = WP[a], B = WP[b];
    if (!A || !B) return;
    if (wpEdgeBlocked(a, b, null)){
      bad.push({ idx, a, b });
    }
  });
  return bad;
}
window.__cs2ScanGraph = function(){
  const bad = scanBlockedEdges();
  if (bad.length === 0){
    alert('✅ Граф чистый — все рёбра проходят вне стен на своих этажах.');
    return;
  }
  const list = bad.map(x => `  #${x.idx}: ${x.a} ↔ ${x.b}`).join('\n');
  const ok = confirm(`Найдено ${bad.length} рёбер, пересекающих стены:\n\n${list}\n\nУдалить их? (Рёбер станет ${EDGES.length - bad.length})`);
  if (ok){
    const drop = new Set(bad.map(x => x.idx));
    EDGES = EDGES.filter((_, i) => !drop.has(i));
    buildAdjFromEdges();
    autoSave(); updateEditInfo();
    alert(`✅ Удалено ${bad.length} битых рёбер.`);
  }
};
window.__cs2ToggleBlockedEdges = function(){
  R.showBlockedEdges = !R.showBlockedEdges;
  const btn = document.getElementById('cs2-rf-blocked-toggle');
  if (btn){
    btn.textContent = R.showBlockedEdges ? '🔴 Скрыть битые рёбра' : '🔴 Показать битые рёбра';
    btn.style.color = R.showBlockedEdges ? '#fff' : '#ff4757';
    btn.style.background = R.showBlockedEdges ? '#ef5364' : '#1a2230';
  }
  renderTips();
};

function exportToFile(){
  const cleanGrenades = GRENADES.map(g=>{const { _usedRound, ...clean } = g; return clean;});
  const roleSnapshot = (t) => ({
    aiRoleBrainEnabled: t?.aiRoleBrainEnabled !== false,
    players: (t?.players || []).map(p => ({nick:p.nick, role:p.role, roleEnabled:p.roleEnabled !== false}))
  });
  const out = {
    n: {},
    e: EDGES.map(([a,b])=>({a,b})),
    walls: WALLS,
    navBlockers: NAV_BLOCKERS,
    grenades: cleanGrenades,
    radarEconomy: R.economy,
    radarCTTactic: R.ctTactic,
    mirageRoles: (typeof T_TEAM !== 'undefined' && typeof CT_TEAM !== 'undefined') ? {T:roleSnapshot(T_TEAM),CT:roleSnapshot(CT_TEAM)} : null
  };
  Object.entries(WP).forEach(([k,p])=>{ out.n[k] = [ +(p.x/RADAR_SIZE).toFixed(6), +(p.y/RADAR_SIZE).toFixed(6), p.z||0 ]; });
  const json = JSON.stringify(out, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `mirage_graph_${Date.now()}.json`;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(url), 1000);
}
function importFromFile(file){
  if (!file) return;
  const r = new FileReader();
  r.onload = ev=>{
    try {
      const data = JSON.parse(ev.target.result);
      if (data.n && data.e){
        WP = {};
        Object.entries(data.n).forEach(([k, v])=>{
          const x = v[0], y = v[1], z = v[2] || 0;
          const isNorm = x <= 2 && y <= 2;
          WP[k] = isNorm ? { x: x*RADAR_SIZE, y: y*RADAR_SIZE, z } : { x, y, z };
        });
        EDGES = data.e.map(e => [e.a, e.b]);
        if (Array.isArray(data.walls)) WALLS = data.walls.map(w => ({...w}));
        if (Array.isArray(data.navBlockers)) NAV_BLOCKERS = data.navBlockers.map(b => ({...b, points:Array.isArray(b.points)?b.points.map(pt=>({...pt})):b.points}));
        if (Array.isArray(data.grenades)) GRENADES = data.grenades.map(g => JSON.parse(JSON.stringify(g)));
        if (data.radarEconomy) R.economy = data.radarEconomy;
        if (data.radarCTTactic) R.ctTactic = data.radarCTTactic;
        if (data.mirageRoles && typeof T_TEAM !== 'undefined' && typeof CT_TEAM !== 'undefined') {
          const applyRoles = (team, snap) => {
            if(!team || !snap) return;
            if(typeof snap.aiRoleBrainEnabled === 'boolean') team.aiRoleBrainEnabled = snap.aiRoleBrainEnabled;
            const byNick = new Map((snap.players || []).map(p=>[p.nick,p]));
            (team.players || []).forEach(p=>{ const r=byNick.get(p.nick); if(!r) return; if(typeof r.role==='string') p.role=r.role; if(typeof r.roleEnabled==='boolean') p.roleEnabled=r.roleEnabled; });
          };
          applyRoles(T_TEAM,data.mirageRoles.T); applyRoles(CT_TEAM,data.mirageRoles.CT);
        }
        normalizeWalls(); normalizeNavBlockers(); normalizeGrenades();
        buildAdjFromEdges();
        refreshSites();
        autoSave(); updateEditInfo();
        alert('✅ Импортировано: ' + Object.keys(WP).length + ' точек, ' + EDGES.length + ' рёбер, ' + WALLS.length + ' стен, ' + NAV_BLOCKERS.length + ' зон запрета, ' + GRENADES.length + ' гранат');
      } else alert('Неверный формат JSON');
    } catch(e){ alert('Ошибка JSON: ' + e.message); }
  };
  r.readAsText(file);
}

