/* ==============================================================
 * v26.5 — INFORMATION MODEL, CT ROTATIONS, LEARNED POSITIONS & FAKE
 * Fixes: CT staying on dead sites, Kitchen/Cashier camping, fake executes,
 * Lurker behavior, distinct defensive anchors, slower/smaller smoke.
 * ============================================================== */
const V265 = {
  maxCTFakePull: 3,
  fakeMinBelief: 0.52,
  realInfoRadius: 430,
  siteHotRadius: 175,
  ctHoldBan: new Set(['kitchen','kassa']),
  backstabPref: {
    A:['ctjungle','jungle','ticket','exit','mid','kontomid'],
    B:['ctjungle','ctsp','jungle','exit','stairs','mid','kontomid']
  }
};

function v265EnsureState(){
  if(!R.knowledge) R.knowledge={T:{},CT:{}};
  if(!R.fakePlan) R.fakePlan=null;
  if(!R.info) v264InitInfo();
}
function v265EnemyEntry(t){
  const site=v264SiteFromPoint(t.x,t.y);
  const wp=findClosestWPTo(t.x,t.y,t.z);
  return {site,wp};
}
function v265LearnEnemy(t, site=null, weight=0.10){
  v265EnsureState();
  if(!t || t.team!=='T') return;
  const e=R.knowledge.T[t.nick] || (R.knowledge.T[t.nick]={A:0,B:0,MID:0,lastSite:'?',lastWP:null,contacts:0,kills:0});
  const info=site ? {site,wp:findClosestWPTo(t.x,t.y,t.z)} : v265EnemyEntry(t);
  const s=info.site||'MID';
  if(e[s]===undefined) e[s]=0;
  e[s]+=weight;
  e.lastSite=s; e.lastWP=info.wp||e.lastWP; e.contacts=(e.contacts||0)+1;
  const total=Math.max(0,e.A)+Math.max(0,e.B)+Math.max(0,e.MID);
  e.pref=total?((['A','B','MID'].sort((a,b)=>(e[b]||0)-(e[a]||0)))[0]):'?';
}
function v265RegisterKill(v,killer){
  if(!v || v.team!=='T') return;
  v265EnsureState();
  const info=v265EnemyEntry(v);
  v265LearnEnemy(v,info.site,0.55);
  const e=R.knowledge.T[v.nick]; e.kills=(e.kills||0)+1;
  if(killer && killer.team==='CT'){
    R.info.log.unshift({t:Date.now(),team:'CT',text:`${killer.nick} killed ${v.nick} • read ${info.site}`,site:info.site});
    if(R.info.log.length>20) R.info.log.length=20;
  }
}
function v265PreferredEnemyEntries(site){
  v265EnsureState();
  const out=[];
  for(const [nick,e] of Object.entries(R.knowledge.T)){
    const total=(e.A||0)+(e.B||0)+(e.MID||0);
    if(total<0.15 || !e.lastWP) continue;
    const weight=(e[site]||0)/Math.max(total,0.01);
    if(weight>0.16 && WP[e.lastWP]) out.push({nick,wp:e.lastWP,w:weight});
  }
  return out.sort((a,b)=>b.w-a.w);
}
function v265CTCandidates(site){
  const banned=site==='B'?V265.ctHoldBan:new Set();
  const c=siteWaypointCandidates(site,195).filter(x=>!banned.has(x.k));
  // Avoid the absolute center of a site: CTs should hold different angles rather than stack on the plant point.
  return c.filter(x=>x.d>=32);
}
function v265PickCTAnchor(site, p, used=new Set()){
  const c=v265CTCandidates(site);
  if(!c.length) return chooseSiteEntryWP(site,(p.planSlot||0)%5,used,false);
  const learned=v265PreferredEnemyEntries(site);
  let best=null,bestScore=-Infinity;
  for(const x of c){
    if(used.has(x.k)) continue;
    let score=0;
    // Spread defenders.
    for(const u of used){
      const q=WP[u]; if(q) score+=Math.min(80,Math.hypot(x.x-q.x,x.y-q.y)*0.16);
    }
    // Learn where opponents repeatedly appear and choose a nearby receiving angle.
    for(const e of learned){
      const q=WP[e.wp]; if(!q) continue;
      const d=Math.hypot(x.x-q.x,x.y-q.y);
      score += Math.max(0,120-d)*e.w;
    }
    score += Math.random()*12;
    if(score>bestScore){bestScore=score;best=x.k;}
  }
  return best || c[(p.planSlot||0)%c.length].k;
}
function v265AssignCTAnchor(p,site,used=new Set()){
  if(!p || p.team!=='CT') return;
  const key=v265PickCTAnchor(site,p,used);
  p.ctHoldSite=site; p.ctHoldAnchor=key; p.entryAnchor=key; p.ctRotateAt=Date.now();
  return key;
}
function v265ReanchorAll(site, onlyChanged=false){
  const ct=R.players.filter(p=>p.alive&&p.team==='CT'&&p.ctAssignment===site);
  const used=new Set();
  // Keep an already valid anchor. Reassign only new/invalid/duplicate anchors.
  ct.forEach(p=>{
    const valid = p.ctHoldSite===site && p.ctHoldAnchor && WP[p.ctHoldAnchor] && !V265.ctHoldBan.has(p.ctHoldAnchor) && !used.has(p.ctHoldAnchor);
    if(valid) used.add(p.ctHoldAnchor);
  });
  ct.forEach(p=>{
    const valid = p.ctHoldSite===site && p.ctHoldAnchor && WP[p.ctHoldAnchor] && !V265.ctHoldBan.has(p.ctHoldAnchor) && used.has(p.ctHoldAnchor);
    // Duplicate anchors are resolved by checking ownership count below.
    const owners=ct.filter(q=>q!==p && q.ctHoldSite===site && q.ctHoldAnchor===p.ctHoldAnchor && WP[q.ctHoldAnchor]).length;
    if(!valid || owners>0){
      const k=v265AssignCTAnchor(p,site,used); if(k) used.add(k);
    }
  });
}
function v265MoveCTToSite(site,count,reason){
  const ct=R.players.filter(p=>p.alive&&p.team==='CT');
  const counts={A:0,B:0,MID:0};
  ct.forEach(p=>counts[p.ctAssignment||'MID']++);
  const need=Math.max(0,count-(counts[site]||0));
  if(!need) return 0;
  const opposite=site==='A'?'B':'A';
  const candidates=ct.filter(p=>(p.ctAssignment||'MID')!==site)
    .sort((a,b)=>{
      const ap=a.ctAssignment==='MID'?0:(a.ctAssignment===opposite?1:2);
      const bp=b.ctAssignment==='MID'?0:(b.ctAssignment===opposite?1:2);
      return ap-bp;
    });
  let moved=0;
  for(const p of candidates){
    if(moved>=need) break;
    p.ctAssignment=site; p.rotateReason=reason; p.ctHoldAnchor=null; moved++;
  }
  if(moved) v265ReanchorAll(site,false);
  return moved;
}
function v265KeepDistinctCTAssignments(){
  for(const site of ['A','B']) v265ReanchorAll(site,false);
}
function v265ObservedBombSite(){
  if(R.bomb.state==='planted'||R.bomb.state==='dropped') return v264SiteFromPoint(R.bomb.x,R.bomb.y);
  const b=R.bomb.carrier;
  if(!b || !b.alive) return null;
  const ct=R.players.filter(p=>p.alive&&p.team==='CT');
  for(const p of ct){
    if(Math.hypot(p.x-b.x,p.y-b.y)<=V265.realInfoRadius && hasLOS(p,b)){
      const s=v264SiteFromPoint(b.x,b.y); if(s!=='MID') return s;
    }
  }
  return null;
}
function v265FakeActivity(){
  v265EnsureState();
  const fp=R.fakePlan;
  if(!fp || !fp.active) return null;
  const now=Date.now();
  if(now-(fp.lastFakeAt||0)>5200) return null;
  return fp.fakeSite;
}
function v265FakeBelief(){
  const fp=R.fakePlan; if(!fp || !fp.active) return 0;
  const utility=fp.utilityStrength||0;
  let belief=0.34 + Math.min(0.34,utility*0.13);
  if((fp.pullCount||0)>=2) belief+=0.12;
  // Tends to decrease when CT has direct bomb evidence on the real site.
  const real=v265ObservedBombSite();
  if(real===fp.mainSite) belief*=0.42;
  return Math.max(0,Math.min(0.94,belief));
}
function v265ChooseBackstabAnchor(mainSite,p){
  const prefs=V265.backstabPref[mainSite]||[];
  for(const k of prefs){
    if(WP[k] && safePath(findClosestWPTo(p.x,p.y,p.z),k,false)) return k;
  }
  return v264ChooseMidAnchor(p);
}
function v265PickFakePreset(p){
  const fp=R.fakePlan; if(!fp || p.nick!==fp.lurkerNick) return null;
  const arr=availableGrenadePresets(p).filter(g=>
    (p.grenades?.[g.type]||0)>0 &&
    Math.abs((p.z||0)-(g.from.z||0))<=1 &&
    Math.hypot(p.x-g.from.x,p.y-g.from.y)<380 &&
    v264SiteFromPoint(g.to.x,g.to.y)===fp.fakeSite &&
    ['smoke','flash','molotov','he'].includes(g.type)
  );
  arr.sort((a,b)=>{
    const aw=a.type==='smoke'?0:a.type==='flash'?1:a.type==='molotov'?2:3;
    const bw=b.type==='smoke'?0:b.type==='flash'?1:b.type==='molotov'?2:3;
    return aw-bw || Math.hypot(p.x-a.from.x,p.y-a.from.y)-Math.hypot(p.x-b.from.x,p.y-b.from.y);
  });
  return arr[0]||null;
}
function v265InitFakePlan(){
  const lurker=T_TEAM.players.find(p=>p.role==='Lurker')?.nick || T_TEAM.players[4]?.nick;
  if(!lurker){R.fakePlan=null;return;}
  const active=Math.random()<0.72;
  if(!active){R.fakePlan=null;return;}
  R.fakePlan={active:true,mainSite:R.tTargetSite,fakeSite:R.tTargetSite==='A'?'B':'A',lurkerNick:lurker,
    fakeStarted:false,fakeFinished:false,utilityStrength:0,lastFakeAt:0,pullCount:0,successful:false,backstab:false};
}
function v265SetTTasks(){
  if(!R.fakePlan || !R.fakePlan.active) return;
  for(const p of R.players.filter(p=>p.team==='T')){
    if(p.nick===R.fakePlan.lurkerNick){p.tTask='LURKER_FAKE';p.tMainSite=R.fakePlan.mainSite;p.tFakeSite=R.fakePlan.fakeSite;}
    else {p.tTask='MAIN_EXECUTE';p.tMainSite=R.fakePlan.mainSite;p.tFakeSite=R.fakePlan.fakeSite;}
  }
}
function v265RecordFake(p,g){
  const fp=R.fakePlan;
  if(!fp || !fp.active || !p || p.team!=='T' || p.nick!==fp.lurkerNick || !g) return;
  const site=v264SiteFromPoint(g.to.x,g.to.y);
  if(site!==fp.fakeSite) return;
  fp.fakeStarted=true; fp.lastFakeAt=Date.now();
  fp.utilityStrength += g.type==='smoke'?1.0:g.type==='flash'?0.85:g.type==='molotov'?1.1:0.65;
  v264AddInfo('CT',`Utility heard/seen on ${site} • possible fake`,'?');
}

/* Information pass: direct bomb sight overrides the old speculative bombSite guess. */
function v265UpdateInfo(){
  v264UpdateInfo();
  v265EnsureState();
  const observed=v265ObservedBombSite();
  if(observed){R.info.CT.bombSite=observed;R.info.CT.lastSite=observed;R.info.CT.confidence=1;}
  else if(R.bomb.state==='carried') R.info.CT.bombSite='?';
  for(const ct of R.players.filter(p=>p.alive&&p.team==='CT')){
    for(const t of R.players.filter(p=>p.alive&&p.team==='T')){
      if(dist(ct,t)<=360 && hasLOS(ct,t)) v265LearnEnemy(t,null,0.035);
    }
  }
  const fakeSite=v265FakeActivity();
  if(fakeSite && !observed){
    const belief=v265FakeBelief();
    R.info.CT.fakeSite=fakeSite;R.info.CT.fakeConfidence=belief;R.info.CT.lastSite=fakeSite;R.info.CT.lastAt=Date.now();
  }else if(R.info.CT.fakeConfidence) R.info.CT.fakeConfidence=Math.max(0,R.info.CT.fakeConfidence-0.006);
}

/* CT tactics now react to actual information and maintain distinct hold positions. */
function v265UpdateCTTactics(initial=false){
  v264ApplyCTTactic(initial);
  v265EnsureState();
  const ct=R.players.filter(p=>p.alive&&p.team==='CT');
  if(initial){
    ct.forEach(p=>{p.ctBaseAssignment=p.ctAssignment||'MID';p.ctHoldAnchor=null;});
    v265KeepDistinctCTAssignments();
    return;
  }
  if(R.bomb.state==='planted') return;
  const observed=v265ObservedBombSite();
  if(observed){
    const total=ct.length,currentTarget=ct.filter(p=>p.ctAssignment===observed).length;
    const desired=Math.min(total>=5?4:3,Math.max(2,total-1));
    if(currentTarget<desired) v265MoveCTToSite(observed,desired,`CONFIRMED INFO: ${observed}`);
    for(const p of ct.filter(p=>p.ctAssignment===observed)) p.rotateReason=`INFO ${observed}`;
    v265KeepDistinctCTAssignments();
    return;
  }
  const fp=R.fakePlan, fakeSite=fp?.fakeSite, fakeConf=R.info?.CT?.fakeConfidence||0;
  if(fakeSite && fakeConf>=V265.fakeMinBelief){
    const before=ct.filter(p=>p.ctAssignment===fakeSite).length;
    const pull=Math.min(V265.maxCTFakePull,fakeConf>=0.78?3:(fakeConf>=0.63?2:1));
    const desired=Math.min(Math.max(1,ct.length-1),before+pull);
    const moved=v265MoveCTToSite(fakeSite,desired,`POSSIBLE FAKE → ${fakeSite}`);
    fp.pullCount=Math.min(4,Math.max(fp.pullCount||0,before+moved));
    fp.successful=(fp.pullCount||0)>=2;
    if(fp.successful) fp.backstab=true;
    v265KeepDistinctCTAssignments();
    return;
  }
  const preset=CT_TACTIC_PRESETS[R.ctTactic]||CT_TACTIC_PRESETS.balanced;
  for(let i=0;i<ct.length;i++) if(!ct[i].ctAssignment) ct[i].ctAssignment=preset.slots[i]||'MID';
  v265KeepDistinctCTAssignments();
}

